class Solution { private static final int MOD=1000000007;private int[] nums;private int[][] memo;private int full;private int dfs(int mask,int last){if(mask==full)return 1;if(memo[mask][last]!=-1)return memo[mask][last];long ways=0;for(int next=0;next<nums.length;next++)if((mask&(1<<next))==0&&(nums[last]%nums[next]==0||nums[next]%nums[last]==0))ways=(ways+dfs(mask|1<<next,next))%MOD;return memo[mask][last]=(int)ways;}public int specialPerm(int[] nums){this.nums=nums;full=(1<<nums.length)-1;memo=new int[1<<nums.length][nums.length];for(int[] row:memo)Arrays.fill(row,-1);long answer=0;for(int start=0;start<nums.length;start++)answer=(answer+dfs(1<<start,start))%MOD;return (int)answer;} }
